          const y = r.y + 2 + this.slideOff();
          return [
            { id: "close", x: r.x + r.w - 25, y, w: 21, h: 11, tip: "Close", icon: "cross", tone: "red" },
            { id: "expand", x: r.x + r.w - 44, y, w: 18, h: 11, tip: "Full-screen aquarium (A)", icon: "expand", tone: "aqua" }
          ];
