        // Full view: a glossy stats pill at the top with an "Ocean" button beside it.
        fullLayout() {
          const W8 = this.game.screen.W;
          const pw = 196, bw = 62;
          const px2 = Math.round(W8 / 2 - (pw + bw + 6) / 2);
          return { pill: { x: px2, y: 6, w: pw, h: 20 }, btn: { x: px2 + pw + 6, y: 7, w: bw, h: 18 }, unpack: { x: px2 - 70, y: 7, w: 64, h: 18 } };
        }
