              if (f.target !== f.lastTarget) {
                f.lastTarget = f.target;
                const tz2 = f.target.z = Math.pow(rng.next(), 1.35) * 0.82;
                if (T2.W < 520 || T2.round) f.target.x = lerp(T2.left(tz2), T2.right(tz2), rng.float(0.12, 0.88));
                f.target.y = lerp(T2.top(tz2), T2.floorAt(f.target.x, tz2), rng.float(0.15, 0.85));
              }
