            const crowd = 1 - clamp01((n2 / cap - 0.65) / 0.7) * 0.6;
            const decor = clamp01((this.decor.length + this.view.plants.length * 0.25 + this.tier * 0.5) / (1.5 + n2 * 0.35));
            const k = 1 - Math.exp(-step / 40);
