              this.bubbles.push({ X: st.X + rng.float(-2, 2), Y: T2.groundZ(st.X, st.z) - 3, z: st.z + rng.float(-0.02, 0.02), vy: -rng.float(20, 34) * (0.5 + v.fishScale * 0.5), r: rng.pick([1, 1, 1, 2, 2, 3]), wob: rng.float(0, TAU) });
