          this.nearMotes = new Motes(26, { x0: 0, y0: sy + 10, x1: W8, y1: H8 - 30 }, { seed: 8, vx: [-5, 5], vy: [-3, 3], sizes: [2, 2, 3], colors: ["#e8fff8", "#c8f4ff"], alpha: [0.12, 0.3], wob: 8 });
