          A2.push({ spr: render(latticeCrane(72, 84), { yaw: 18, pitch: 12 }), x: LW * 0.2, y: baseA + 2, z: 0.99 });
          const ridgeA = ridgeStrip(73, LW, { amp: 9, base: 7, d: 16, cols: ["#6a6a58", "#5a5a4a", "#4a4a3e"], rocks: { cols: ["#6a5a4a", "#5a6066", "#7a4a34", "#4a5a6a"] } });
