            [0.56, -0.18],
            [0.61, 0.1],
            [0.75, -0.08],
            [0.8, 0.2],
            [0.92, -0.1],
            [0.995, 0.1],
            [0.05, 0.5],
            [0.22, 0.62],
            [0.38, 0.55],
            [0.6, 0.6],
            [0.77, 0.66],
            [0.9, 0.5],
            [0.12, 0.85],
            [0.46, 0.8],
            [0.7, 0.95]
