          const vents = [], chimneys = [];
          S9("vo_basalt0", () => basaltModel(3, 1), 0.2, 0.22, 0.85);
          S9("vo_rock0", () => lavaRockModel(5, 1), 0.65, 0.08, 0.8);
          S9("vo_obsid0", () => obsidianModel(7, 0.9), 0.77, 0.24, 0.85);
