          chimneys.push(S9("vo_sulfur0", () => sulfurModel(13, 1), 0.31, 0.5, 1));
          S9("vo_obsid1", () => obsidianModel(17, 1.1), 0.62, 0.42, 1);
          S9("vo_basalt1", () => basaltModel(19, 1.2), 0.72, 0.56, 1);
          P5("vent_chimney", 0.555, 0.6, 0.85);
          P5("tube_worms", 0.53, 0.52, 0.55, 1);
