          this.ash = new Motes(140, { x0: 0, y0: sy, x1: W8, y1: H8 }, { seed: 5, vx: [-3, 3], vy: [4, 10], sizes: [1, 1, 2], colors: ["#5a5054", "#7a7074", "#3a3438", "#9a9094"], alpha: [0.3, 0.8], wob: 4 });
          this.sulfur = new Motes(70, { x0: 0, y0: sy, x1: W8, y1: H8 }, { seed: 7, vx: [-2, 2], vy: [-3, 2], sizes: [1, 2], colors: ["#d8e05a", "#c8c040", "#e8f08a"], alpha: [0.2, 0.6], wob: 6 });
