          if (pl.t < 2) for (let i = 0; i < 3; i++) this.bubbles.emit(pl.x + (Math.random() - 0.5) * 16, pl.top - Math.random() * 10, { r: 1 + Math.floor(Math.random() * 3), vy: -60 - Math.random() * 60 });
