              if (L4.width !== W8 || L4.height !== H8) {
                L4.width = W8;
                L4.height = H8;
              }
              const g = ctxOf(L4);
              g.setTransform(1, 0, 0, 1, 0, 0);
              g.clearRect(0, 0, W8, H8);
