          if (pop < 1) {
            ctx2.translate(bx + bw / 2, by + bh);
            ctx2.scale(pop, pop);
            ctx2.translate(-(bx + bw / 2), -(by + bh));
          }
          ctx2.drawImage(aeroCached(`dotsay|${bw}|${bh}`, () => aeroSurface(bw, bh, { tone: "white", r: 7, gloss: 0.55, glossH: 7, curve: 2, rim: 0.9, glow: 0.3, edge: "#5aa8d8" })), bx, by);
          ctx2.fillStyle = "#ffffff";
          for (let i = 0; i < 5; i++) ctx2.fillRect(Math.round(bx + bw / 2 - 5 + i), by + bh - 1 + i, 6 - i, 1);
          ctx2.fillStyle = "#5aa8d8";
          for (let i = 0; i < 5; i++) ctx2.fillRect(Math.round(bx + bw / 2 + 1), by + bh - 1 + i, 1, 1);
          const shown = S9.t < 0.25 ? 0 : Math.floor((S9.t - 0.25) * 60);
          let left = shown;
          lines.forEach((ln, i) => {
            const part2 = left >= ln.length ? ln : ln.slice(0, Math.max(0, left));
            left -= ln.length;
            drawText(ctx2, part2, bx + bw / 2, by + 6 + i * 10, { align: "center", color: INK7 });
          });
          ctx2.restore();
          const talking = shown < lines.join("").length;
          const px2 = L4.x + L4.w / 2, py = L4.y + 152;
          ctx2.drawImage(aeroCached("shoppodium", () => aeroSurface(72, 12, { tone: "aqua", r: "pill", gloss: 0.8, glossH: 5, curve: 1, rim: 0.9, glow: 0.7 })), Math.round(px2 - 36), py - 2);
          drawAeroLeaf(ctx2, px2 + 30, py + 2, 16, 9, -30, { tone: "lime" });
          drawAeroLeaf(ctx2, px2 - 30, py + 3, 14, 8, -150, { tone: "leaf", flip: true });
          const cheer = S9.pose === "cheer" && S9.t < 1.4;
          const lookAt = g.input ? [g.input.x, g.input.y] : null;
          try {
            drawNPC(ctx2, "dot", { x: px2, y: py - 2, t, scale: 1.45, facing: 1, pose: cheer ? "cheer" : talking ? "talk" : "idle", talk: talking ? 0.5 + 0.5 * Math.sin(t * 22) : 0, mood: S9.mood, lookAt, shadow: false });
          } catch (e) {
            if (!this.npcErr) {
              this.npcErr = true;
              console.error(e);
            }
          }
          if (cheer && t * 6 % 1 < 0.2) drawSparkle(ctx2, px2 + 22, py - 70, 3, 1);
          const lvI = shop2.levelIndex(), lv = shop2.level();
          let y = L4.y + 166;
          ctx2.drawImage(aeroCached(`shoplv|${L4.w - 12}`, () => aeroSurface(L4.w - 12, 16, { tone: "white", r: "pill", gloss: 0.7, glossH: 7, curve: 1, rim: 0.8, glow: 0.4, a: [0.92, 0.92] })), L4.x + 6, y);
          drawText(ctx2, lv.name, L4.x + 12, y + 5, { color: INK7 });
          for (let i = 1; i < SHOP_LEVELS.length; i++) drawGlossOrb(ctx2, L4.x + L4.w - 12 - (SHOP_LEVELS.length - 1 - i) * 7, y + 8, 2.5, i <= lvI ? SHOP_LEVELS[i].color : "#c8d6e0");
          y += 21;
          const left0 = shop2.restockIn();
          const k = clamp(1 - left0 / lv.restock, 0, 1);
          ctx2.drawImage(getUiIcon("clock"), L4.x + 7, y);
          drawAeroBar(ctx2, L4.x + 20, y + 1, L4.w - 58, 8, k, { color: "#5cc832" });
          drawText(ctx2, formatShortTime(left0), L4.x + L4.w - 7, y + 1, { align: "right", font: "small", color: INK_SOFT4 });
          if (ui.hover({ x: L4.x, y: y - 2, w: L4.w, h: 12 })) ui.tip = "Shelves restock";
          y += 15;
          const perks = [];
          if (lv.discount > 0) perks.push([`-${Math.round(lv.discount * 100)}%`, "#ff9d2e"]);
          perks.push([TIERS[lv.grade].short, TIERS[lv.grade].color]);
          let tx = L4.x + 7;
          for (const [p, c] of perks) tx += tag(ctx2, tx, y, p, c) + 3;
