  function ocean(g, t = 0) {
    const top = [63, 184, 196], bot = [18, 74, 110];
    for (let y = 0; y < H6; y++) {
      const k = y / H6;
      for (let band = 0; band < 2; band++) {
        const kk = Math.min(1, k + band * 0.012);
        g.fillStyle = `rgb(${Math.round(top[0] + (bot[0] - top[0]) * kk)},${Math.round(top[1] + (bot[1] - top[1]) * kk)},${Math.round(top[2] + (bot[2] - top[2]) * kk)})`;
        if (band === 0) g.fillRect(0, y, W6, 1);
      }
    }
    g.fillStyle = "rgba(255,255,255,0.05)";
    for (let i = 0; i < 7; i++) {
      const x0 = 80 + i * 140;
      g.beginPath();
      g.moveTo(x0, 0);
      g.lineTo(x0 + 40, 0);
      g.lineTo(x0 - 60, H6);
      g.lineTo(x0 - 120, H6);
      g.fill();
    }
    g.fillStyle = "rgba(220,250,255,0.35)";
    for (let i = 0; i < 60; i++) {
      const x = i * 157 % W6, y = (i * 263 + 40) % H6, r = 1 + i % 3;
      g.fillRect(x, y, r, r);
    }
  }
